class AnotherLineContentAnnotation extends LineContentAnnotation {
    public AnotherLineContentAnnotation(Position p, ICodeMiningProvider provider) { super(p, provider); }
    private StyledText getTextWidget() { 
        // Mock method for example
        return new StyledText(null, 0); 
    }

    // Rule should not match because of different comparison operator
    boolean someOtherMethod(int widgetOffset) {
        return getTextWidget().getLineAtOffset(widgetOffset) != getTextWidget().getLineAtOffset(widgetOffset - 1);
    }

    // Rule should not match because it already contains a similar guard
    boolean alreadyGuarded(int widgetOffset) {
        return widgetOffset >= 0 && getTextWidget().getLineAtOffset(widgetOffset) == getTextWidget().getLineAtOffset(widgetOffset - 1);
    }

    // Rule should not match if the receiver is not LineContentAnnotation
    boolean unrelatedMethod(int offset, Object receiver) {
        return ((StyledText)receiver).getLineAtOffset(offset) == ((StyledText)receiver).getLineAtOffset(offset - 1);
    }
